{
  "technical_and_design_decisions": [
    "Create a new external Go module github.com/hyperledger/fabric-lib-go to host externalized packages (protoutil, bccsp, msp, discovery) as suggested in U5-U8.",
    "For U1, refactor the statebased package to depend only on fabric-protos-go (and standard library), removing cauthdsl and protoutil by reimplementing policy construction directly with protobuf messages.",
    "For U2, refactor the entities package to use the externalized BCCSP from fabric-lib-go and standard logging instead of fabric flogging, eliminating all fabric/* imports.",
    "For U3/U4, update the marbles02_private example in fabric-samples to add `tr -d '\\n'` to base64 export commands and clarify with comments.",
    "Maintain API compatibility for externalized packages to minimize changes for existing consumers; use Go modules with semantic versioning.",
    "Replace internal copies of BCCSP, MSP, and discovery in fabric-sdk-go with references to the external fabric-lib-go module."
  ],
  "assumptions": [
    "The developer is familiar with the Hyperledger Fabric and Fabric SDK Go codebases and Go module management.",
    "The fabric-protos-go module already exists and is used for protobuf definitions, so externalized packages can depend on it.",
    "Existing unit and integration tests for the affected packages are sufficient and will be adapted during refactoring; no major new test development is required.",
    "The marbles02_private issue is limited to documentation/example commands in the fabric-samples repository, not core chaincode logic.",
    "Basic CI and repository scaffolding for fabric-lib-go can be set up quickly using existing Hyperledger templates.",
    "Effort estimates exclude code review cycles, meetings, and elapsed calendar time; they represent focused development work by a single person."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Refactor statebased package (U1)",
      "activity_description": "Modify core/chaincode/shim/ext/statebased to remove all fabric/* dependencies except fabric/protos/*. Reimplement cauthdsl and protoutil usage directly with protobuf messages and standard library. Update tests and verify with `go list` that only protos remain.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2",
      "activity_name": "Refactor entities package (U2)",
      "activity_description": "Modify core/chaincode/shim/ext/entities to remove imports of fabric bccsp, factory, sw, utils, and flogging. Use externalized BCCSP from fabric-lib-go and standard logging. Update code and tests to compile and pass.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "Fix marbles02_private example (U3/U4)",
      "activity_description": "Update fabric-samples marbles02_private documentation and example export commands to include `tr -d '\\n'` (or equivalent) to prevent base64 newline JSON parsing errors, and add explanatory comments as suggested.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A4",
      "activity_name": "Set up fabric-lib-go external module",
      "activity_description": "Create the new github.com/hyperledger/fabric-lib-go repository with Go module definition, LICENSE, directory layout for protoutil, bccsp, msp, discovery, and minimal CI.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize protoutil (U5)",
      "activity_description": "Move protoutil from fabric to fabric-lib-go, replace fabric-specific imports with fabric-protos-go, ensure API compatibility, tag a release, and update Fabric and SDK imports to use the external package.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize BCCSP (U6)",
      "activity_description": "Extract bccsp and subpackages (factory, sw, idemix, signer, utils) to fabric-lib-go. Remove fabric common/flogging dependencies, use external logging and fabric-protos-go. Update Fabric and fabric-sdk-go to consume external BCCSP and delete internal SDK copy.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize MSP (U7)",
      "activity_description": "Extract msp package and subpackages to fabric-lib-go, leveraging external BCCSP and fabric-protos-go. Remove fabric-internal dependencies, update Fabric and SDK consumers, and remove internal SDK MSP copy.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize discovery client (U8)",
      "activity_description": "Extract discovery client code from fabric to fabric-lib-go, replace fabric imports with external equivalents, publish, and update Fabric/SDK consumers to use the external module.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration and import path updates",
      "activity_description": "Update go.mod files across Fabric, fabric-sdk-go, and fabric-samples to reference fabric-lib-go and fabric-protos-go. Adjust import paths globally, build all modules, and fix any breakages from the refactor.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A10",
      "activity_name": "Testing and acceptance verification",
      "activity_description": "Run unit and integration tests for modified packages, verify acceptance criteria (e.g., `go list` shows only protos for statebased, no fabric deps for entities, external packages build independently), and update relevant documentation.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 46.5
  }
}

